   FineLetThemSettleThere: "Pekâlâ, bırakın oraya yerleşsinler",
   AfricaMustBeDefendedAtAllCosts: "Afrika ne pahasına olursa olsun müdafaa edilmelidir",
   NegotiateAndContainThem: "Onlarla müzakere et ve onları zapturapt altına al",
   HmmOneMoreThreatToDealWith: "Hmm... İcabına bakılacak bir tehdit daha",
   LetsHopeTheyStayPeaceful: "Umarız barışçıl kalırlar",
   WeShallPrepareForThisNewThreat: "Bu yeni tehdide karşı hazırlık yapacağız",
   LetUsSeeWhatComesOfThis: "Bakalım bunun sonu nereye varacak",
