   BarbariansWillNotRaidIfAttitudeIsPositive: "Barbarlar, bize karşı tutumları pozitif olduğu müddetçe eyaletimize akın düzenlemeyecektir.",
   AttitudeTowardsUs: "Bize Karşı Tutum",
   $1IsCurrentlyReceivingASignificantWarPowerBoostThatWillEndIn$2Months: "$1, şu anda $2 ay içinde sona erecek olan mühim bir savaş gücü takviyesi almaktadır.",
