   OurReligionIsNotChristian: "Dinimiz Hristiyanlık değil",
   OurReligionIsChristian: "Dinimiz Hristiyanlık",
   OurProvinceReligionIsChristian: "Eyaletimizin dini Hristiyanlıktır",
   TileReligionIsNotChristian: "Toprak dini Hristiyanlık değil",
   ChristianInfluenceConversionEffectsDescription: "Dinimiz Hristiyanlık değilken Hristiyan Nüfuzu Yönetim Maliyetinden yüksekse yahut dinimiz Hristiyanlık iken düşükse, aşağıdaki etkiler tatbik edilir.",
   ChristianInfluence: "Hristiyan Nüfuzu",
   ChristianInfluencePerYear: "Yıllık Hristiyan Nüfuzu",
   ChristianInfluencePerYearDesc: "Bu, eyaletimizin her yıl kazandığı Hristiyan Nüfuzu miktarıdır.",
   $1ChristianInfluenceIsAtLeast$2: "$1'in Hristiyan Nüfuzu en az $2",
   ChristianInfluenceIsHigherThanGoverningCost: "Hristiyan Nüfuzu, Yönetim Maliyetinden yüksektir",
   $1SpreadsTo$2And$3OfTheChristianTiles: "$1, $2'ye ve Hristiyan topraklarının $3'üne yayılır.",
   TheSchismAtCarthage: "Kartaca Bölünmesi",
   TheSchismAtCarthageDesc: "Caecilianus'un Kartaca piskoposu olarak takdis edilmesi Africa Kilisesi'ni ikiye böldü. Muhalifleri, takibat esnasında mukaddes metinleri teslim etmekle itham edilen ruhbanları reddediyor ve ihanetle lekelenmiş bir kilisenin hakiki sakramentleri ifa edemeyeceğinde ısrar ediyor.",
   TheAfricanChurchIsDivided: "Africa Kilisesi bölündü",
   AriusChallengesTheBishops: "Arius Piskoposlara Meydan Okuyor",
   AriusChallengesTheBishopsDesc: "Arius adında bir rahip, Oğul'un Baba tarafından yaratıldığını ve ezelden beri var olmadığını vaaz ediyor. İskenderiye'de telin edilmesi onu susturmaya yetmedi; doğu eyaletlerindeki piskoposlar ve cemaatler birer birer safını seçiyor.",
   TheControversySpreads: "İhtilaf yayılıyor",
   TheSpiritIsCalledIntoQuestion: "Kutsal Ruh Sorgulanıyor",
   TheSpiritIsCalledIntoQuestionDesc: "Konstantinopolisli Makedonius'un müritleri Oğul'un ilahlığını kabul etse de Kutsal Ruh'un Baba ve Oğul ile eşit olduğunu reddediyor. Öğretileri Trakya ve Asya'da piskoposları ve cemaatleri saflarına katarak, birçoğunun hallolduğunu umduğu ihtilafları yeniden alevlendiriyor.",
   TheCreedIsContestedOnceMore: "Akide bir kez daha ihtilaf konusu oluyor",
   TheTeachingsOfPelagius: "Pelagius'un Öğretileri",
   TheTeachingsOfPelagiusDesc: "Britannialı bir çilekeş olan Pelagius, her insanın masum doğduğunu ve hür iradesiyle salah yolunu seçebileceğini öğretiyor. Fikirleri İtalya'dan Africa'ya değin hayranlar bulurken, Hippolu Augustinus bunların ilahi inayete ziyadesiyle az yer bıraktığı hususunda ikazda bulunuyor.",
   TheDebateOverGraceBegins: "İnayet üzerine münakaşa başlıyor",
   NestoriusRejectsTheotokos: "Nestorius Theotokos'u Reddediyor",
   NestoriusRejectsTheotokosDesc:
      "Konstantinopolis piskoposu makamına yeni oturan Nestorius, Meryem'e 'Theotokos', yani Tanrı Anası unvanının atfedilmesine itiraz ediyor. Onun vaazları, Mesih'in insani ve ilahi tabiatlarının ne suretle birleştiğine dair çok daha geniş bir münakaşayı alevlendiriyor ve bu ihtilaf Şark Kilisesi boyunca yayılıyor.",
   ThePulpitsRingWithControversy: "Kürsüler ihtilaf sesleriyle inliyor",
   ChalcedonDividesTheEast: "Khalkedon Şark'ı Bölüyor",
   ChalcedonDividesTheEastDesc:
      "Khalkedon (Kadıköy) Konsili, Mesih'in iki tabiatta tek bir şahıs olduğunu ilan etti, lakin Mısır ve Suriye'deki pek çok Hristiyan bu formülü reddediyor. Onlar Kelam'ın tecessüm etmiş tek ve birleşik tabiatını müdafaa ediyor ve bu mutabakatı İskenderiyeli Kyrillos'a bir ihanet olarak telin ediyorlar.",
   TheCouncilHasNotBroughtPeace: "Konsil beraberinde sulh getirmedi",
   OneWillInChrist: "Mesih'te Tek İrade",
   OneWillInChristDesc: "İmparator Herakleios, Mesih'in iki tabiata lakin tek bir iradeye sahip olduğunu beyan eden yeni bir formülü tasdik etti. Khalkedoncular ile Miafizitleri uzlaştırmak gayesiyle ortaya atılan bu akide, tam aksine Roma'dan şark patrikhanelerine kadar taze bir mukavemet dalgası kışkırtıyor.",
   TheCompromiseSatisfiesNoOne: "Bu uzlaşma kimseyi hoşnut etmiyor",
   TheWarAgainstTheIcons: "İkonalara Karşı Savaş",
   TheWarAgainstTheIconsDesc:
      "İmparatorluk memurları, onlara hürmet göstermenin putperestliğin bir nevi olduğunu ilan ederek mukaddes tasvirleri kiliselerden ve amme alanlarından söküp atıyor. Keşişler, piskoposlar ve müminler ikonaları müdafaa ediyor; bu ihtilaf imparatorluğun dört bir yanındaki cemiyetleri ikiye bölüyor.",
   SacredImagesBecomeABattleground: "Mukaddes tasvirler bir muharebe meydanına dönüşüyor",
   TheirReligionIsNotChristian: "Onların dini Hristiyanlık değil",
