   $1PrestigeForEachCoreCoastalTileUpTo$2: "Her çekirdek sahil toprağı için $1 Prestij (en fazla $2)",
   LittoralTaxDistricts: "Kıyı Vergi MıntıkaIarı",
   LittoralTaxDistrictsDesc$1$2: "En az $2 sahil kenarına sahip her çekirdek sahil toprağı için tüm topraklarda $1 Arazi Vergisi",
   MercantileMobilization: "Ticari Seferberlik",
   $1WarPowerForEachActiveTrade: "Her aktif ticaret için $1 Savaş Gücü",
   GranaryOfTheEmpire: "İmparatorluğun Tahıl Ambarı",
   GranaryOfTheEmpireDesc$1$2: "Tahıl üreten her çekirdek toprak için tüm topraklarda $1 Toprak Çıktısı (en fazla $2)",
   ProvinceWesternRomanEmpire: "Batı Roma İmparatorluğu",
   TheWesternRomanEmpireRestored: "Batı Roma İmparatorluğu İhya Edildi",
   WesternRomanEmpireRestoredDesc: "Britannia'dan Afrika'ya değin Batı eyaletleri bir kez daha tek bir otoriteye biat ediyor. Kadim hudutlar emniyete alındı, Roma kanunları hüküm sürüyor ve imparatorluk payesini kuşanmak artık hakkımızdır. Cihan bilsin ki Batı Roma İmparatorluğu ihya edilmiştir.",
   TheWestIsRomanOnceMore: "Batı bir kez daha Romalıdır",
   DominionOfTheWesternSea: "Batı Denizi Tahakkümü",
   DominionOfTheWesternSeaDesc:
      "Herkül Sütunları'ndan Adriyatik'e ve Galya'dan Afrika'ya kadar, batı denizinin her bir limanı ve adası artık bize biat ediyor. Ticaret yolları, deniz üsleri ve eyalet başkentleri kıyıları tek bir tahakküm altında birleştiriyor. Romalılar bu sulara Mare Nostrum derdi. Bir kez daha, bu deniz bizimdir.",
   GovernTheShoresThroughLaw: "Kıyıları kanunla idare et",
   BindThePortsThroughDiplomacy: "Limanları diplomasiyle perçinle",
   EntrustTheSeaToOurFleets: "Denizi donanmalarımıza emanet et",
   DominionOfTheEasternSea: "Doğu Denizi Tahakkümü",
   DominionOfTheEasternSeaDesc: "Adriyatik'ten Nil'e ve Achaia'dan Suriye'ye kadar, doğu denizinin her büyük limanı ve adası artık bize biat ediyor. Ege'nin, Anadolu'nun, Levant'ın ve Mısır'ın serveti limanlarımızdan akarken, donanmalarımız her bir geçidi muhafaza ediyor. Doğu Akdeniz, tahakkümümüzün temelidir.",
   GovernTheEasternShoresByLaw: "Doğu kıyılarını kanunla idare et",
   BindTheEasternPortsByTreaty: "Bind the eastern ports by treaty",
   EntrustTheEastToOurFleets: "Doğuyu donanmalarımıza emanet et",
