   InflameTheGallicFactions: "Galya hiziplerini kışkırt",
   BritanniaRulesNorthernGaul: "Britannia Kuzey Galya'ya Hükmediyor",
   BritanniaRulesNorthernGaulDesc: "Kuzey Galya ve Ren hududu artık Britannia'ya biat ediyor. Fetih, kadim şehirlerden, zengin malikanelerden ve kudretli ordulardan müteşekkil kıtasal bir diyar yarattı, lakin onun hususiyeti bu toprakları ada eyaletine ne suretle perçinleyeceğimize bağlı olacaktır.",
