   BritanniaReachesTheMediterranean: "Britannia Akdeniz'e Ulaşıyor",
   BritanniaReachesTheMediterraneanDesc: "Nesiller boyu kuzey okyanusuna baktıktan sonra Britannia artık Akdeniz'e açılan kalıcı bir çıkışa sahip. Güney limanlarının gümrükleri, sulh hakimlerinin ihtisası ve denizleri aşan bir diyarın methiyesi; her biri birbirinden farklı mükafatlar sunuyor.",
