   ABritannianFootholdInHispania: "Hispania'da Bir Britanya Köprübaşı",
   ABritannianFootholdInHispaniaDesc: "Sancaklarımız Pireneler'i aştı ve Tarraconensis'teki bir dizi hisar artık Britannia'nın Hispania'ya girişini emniyete alıyor. Malikaneleri, tecrübeli hakimleri ve siyasi prestiji derhal mükafatlar sunarken, yarımadanın içlerine uzanan yollar bizi ileriye çağırıyor.",
