   LaunchGame: "Oyunu Başlat",
   InstalledMods: "Yüklü Modlar",
   ModsManagerDescription: "İki tür mod mevcuttur: <i>eklenti (addon)</i> ve <i>kapsamlı dönüşüm (total conversion)</i>. Birden fazla eklenti modu yüklenebilir, lakin sadece tek bir kapsamlı dönüşüm modu yüklenebilir. Modlar birbiriyle uyumlu olmayabilir. Oyun en son yüklenen modları hatırlar.",
   Addon: "Eklenti",
   TotalConversion: "Kapsamlı Dönüşüm",
   Loading$1: "$1 yükleniyor...",
   TutorialIncreaseGameSpeedDesc$1$2$3:
      "Her ay $1 taarruz teşebbüsünde bulunulur ve nihai netice bu sonuçların ekseriyetine göre tayin edilir. Şayet muvaffak olunursa $2 savaş skoru kazanırız; aksi takdirde aynı miktarda skor kaybederiz.<br>Savaş devam ederken, oyun hızını $3 seviyesine çıkarmak için ekrandaki talimatları izleyin.",
   TutorialSignPeaceTreatyAfterVictoryDesc$1:
      "İcab eden savaş skoruna ulaştığımızda, sağdaki devam eden savaş simgesi zıplayacaktır. Ona tıklayın ve <Tile>$1</Tile> toprağını işgal etmemize müsaade eden bir barış antlaşması akdetmek için ekrandaki talimatları izleyin.<br>Rahatça hareket edebilmemiz için oyunu duraklatmayı yahut oyun hızını düşürmeyi göz önünde bulundurun.",
   AdoptASocialClassAgenda: "Bir içtimai sınıf gündemi benimse",
   TutorialSocialClassAgendaDesc:
      "Eyaletimizin, her biri farklı gündemleri destekleyen yahut onlara muhalefet eden muhtelif içtimai sınıfları mevcuttur. Bir gündemi benimsemek için ekrandaki talimatları izleyin—böylece destekleyen sınıfların nüfuzu artarken, muhalif sınıfların sadakati azalacaktır.<br>Herhangi bir içtimai sınıfın ziyadesiyle nüfuzlu yahut sadakatsiz hale gelmesine müsaade etmemeye dikkat edin, zira bu menfi neticelere yol açacaktır.",
   LetMissionsGuideOurRestoration: "Let missions guide our restoration",
   TutorialMissionsDesc$1$1:
      "Her eyaletin kendine has bir görev silsilesi vardır; her bir görevi tamamlamak bize muhtelif mükafat seçenekleri sunar. <icon>Mission</icon><i>$1</i> görevini görüntülemek için ekrandaki talimatları izleyin—tafsilatını görmek için her bir mükafat seçeneğinin üzerine gelin.<br>İlk birkaç denememizde, erkenden bir ivme kazanmak namına görevleri takip etmek isabetli bir karardır.<br>Eğitim, <i>$1</i> görevini tamamladıktan yahut aşağıdaki düğmeye tıkladıktan sonra devam edecektir.",
