   TheAlamanniBreakTheFrontier: "Alamanniler Hududu Yarıyor",
   TheAlamanniBreakTheFrontierDesc: "Büyük bir Alamanni akını Yukarı Cermen-Raetia hududunu vuruyor. Batı Raetia'daki her hisarı ve yerleşimi muhafaza edecek kadar askerimiz olmadığından, meclisimiz eyalet müdafaasının nerede tutunacağına karar vermemizi talep ediyor.",
