   TheBrennerPassLiesOpen: "Brenner Geçidi Ardına Kadar Açık",
   TheBrennerPassLiesOpenDesc: "Bir Alamanni ordusu, Roma orduları başka yerlerdeki buhranlarla boğuşurken Brenner Geçidi'ni aşıp kuzey Italia'ya giriyor. İmparator Claudius yetişmeden evvel, tükenmiş garnizonlarımızın bu Alp yolunda onlara kafa tutup tutmayacağına karar vermeliyiz.",
