   OfferTheLentiensesNewTerms: "Lentienselere yeni şartlar sun",
   ValentiniansFrontierTowers: "Valentinianus'un Hudut Kuleleri",
   ValentiniansFrontierTowersDesc: "Valentinianus'un hududu tahkim etme emri makamımıza ulaştı. Hazine, imparatorluk mühendisleri tarafından teklif edilen her kuleyi ve ambarı inşa edemez; bu sebeple programın Raetia'ya düşen payı için öncelikleri tayin etmeliyiz.",
