   BautoCallsTheSteppeWarriors: "Bauto Bozkır Savaşçılarını Çağırıyor",
   BautoCallsTheSteppeWarriorsDesc: "Juthungiler Raetia Secunda'nın zengin topraklarını yağmalıyor. Bauto, idaremizden hudut ötesinden çağırdığı Hunlar ve Alanların maaşlarını ödemesini ve onları barındırmasını istiyor; böylece bir tehlikeyi, sadakati sikkelere ve yağmaya dayalı yardımcı birliklerle ikame ediyor.",
   PayBautosHunsAndAlans: "Bauto'nun Hunlarına ve Alanlarına ödeme yap",
   MusterTheRaetianLimitanei: "Raetia limitanei birliklerini topla",
   SendEnvoysToBuyAWithdrawal: "Geri çekilmelerini satın almak için elçiler yolla",
   StilichosWinterInRaetia: "Stilicho'nun Raetia'daki Kışı",
   StilichosWinterInRaetiaDesc: "Raetia'daki Vandal ve Alan akınını bastırdıktan sonra Stilicho, Alarik'in Italia'ya ilerleyişini karşılamak üzere birliklere güneye gitmelerini emrediyor. Müdafaasız kalan eyaletimizi emniyette tutarken bu emre ne ölçüde riayet edeceğimize karar vermeliyiz.",
   ReleaseTheTroopsForItalia: "Birlikleri Italia için serbest bırak",
   KeepTheAlpinePassesManned: "Alp geçitlerindeki garnizonları muhafaza et",
   PetitionToSettleThemAsFederates: "Onları foederati olarak iskan etmek için arzuhal sun",
   BurcoAtTheCampiCannini: "Burco Campi Cannini'de",
   BurcoAtTheCampiCanniniDesc: "Dokuz yüz Alemanni eyaletimizi geçip Italia'ya doğru iniyor, orada Majorianus'un subayı Burco onları Campi Cannini'de imha ediyor. Şimdi idaremizden geçitleri emniyete almamızı ve hayatta kalan esirlerin akıbetini tayin etmemizi talep ediyor.",
   HuntTheSurvivorsThroughTheAlps: "Sağ kalanları Alpler boyunca avla",
   StrengthenTheAlpineWatch: "Alp nöbetçilerini takviye et",
   RecruitTheCapturedWarriors: "Esir alınan savaşçıları saflara kat",
   ARealmBeyondTheNorthernFrontier: "Kuzey Hududunun Ötesinde Bir Diyar",
   ARealmBeyondTheNorthernFrontierDesc: "Sancaklarımız artık Portus'ta ve Raetia'nın kuzey hududunun ötesinde dalgalanıyor. Bir zamanlar Alp geçitleriyle tanımlanan eyaletimiz, şimdi Germania'da bir köprübaşına sahip ve bu umulmadık diyarın neye dönüşeceğine karar vermeliyiz.",
