   TheCentonariiOfFlaviaSolvaDesc:
      "Septimius Severus ve Caracalla'nın bir fermanı, amme hizmetlerinden kaçmak için loncaya katılan zenginleri hariç tutarken, Flavia Solva'nın çalışan centonariilerine tanınan imtiyazları tasdik ediyor. Sulh hakimlerimiz, collegium sicillerini gözden geçirirken bu ayrımı tatbik etmelidir.",
