   EndEveryExemption: "Tüm muafiyetlere son ver",
   RaidsOnTheNoricanFrontier: "Noricum Hududuna Akınlar",
   RaidsOnTheNoricanFrontierDesc: "Raporlar, yukarı Tuna müdafaa hatlarını aşıp Noricum'a yapılan akınlardan Alamanni savaş çetelerini mesul tutuyor. Hudut yerleşimleri bizden birlikler talep ederken, müdafaasız toprak sahipleri barışı satın almamız için bizi sıkıştırıyor.",
   ReinforceTheNoricanLimes: "Noricum hudut hattını takviye et",
   MeetThemWithFieldTroops: "Onları sahra birlikleriyle karşıla",
   PayTheRaidersToWithdraw: "Geri çekilmeleri için akıncılara ödeme yap",
   ValeriansNorthernMuster: "Valerianus'un Kuzey Celbi",
   ValeriansNorthernMusterDesc: "İmparator Gallus, Valerianus'a Aemilianus'a karşı Raetia ve Noricum'da birlikler toplamasını emretti. Valerianus'un kurmayı; erzak, acemi erler ve eyalet idaremizin tam teşekküllü işbirliğini talep ediyor.",
   ProvisionValeriansArmy: "Valerianus'un ordusunu donat",
   ReinforceLegioIIItalica: "Legio II Italica'yı takviye et",
   KeepOurRecruitsAtHome: "Acemi erlerimizi memlekette tut",
   DiocletiansFrontierReforms: "Diocletianus'un Hudut Islahatları",
   DiocletiansFrontierReformsDesc: "Diocletianus idaresinde, daha muhkem hudut müdafaalarına yönelik yeni imparatorluk talepleri Noricum'a ulaştı. Mühendislerimiz daha muhkem hisarlar, daha derin erzak depoları ve Tuna garnizonlarını uzak tersaneleri beklemeden teçhiz edebilecek atölyeler teklif ediyor.",
