   RequireLaborFromNearbyTowns: "Civardaki kasabalardan işgücü talep et",
   AlaricWaitsInNoricum: "Alarik Noricum'da Bekliyor",
   AlaricWaitsInNoricumDesc: "Alarik ve Gotları Noricum'da ordugâh kurdular ve terk edilmiş bir sefer için imparatorluk sarayından dört bin libre altın talep ediyorlar. Saray cevap verene dek, orduları erzaklarını kasabalarımızın ve yollarımızın kıyısındaki topraklardan temin ediyor.",
   SupplyTheGothicCamp: "Got ordugâhını ikmal et",
   CloseTheRoadsAndPasses: "Yolları ve geçitleri kapat",
   PetitionTheCourtToPay: "Ödeme yapması için saraya arzuhal sun",
   TheEvacuationOfNoricum: "Noricum'un Tahliyesi",
   TheEvacuationOfNoricumDesc: "Odoacer'in kuvvetleri Rugi krallığını imha ettikten sonra, biraderi Onoulphus nehir kıyısındaki Noricum'da kalan Romalı tebaanın Italia'ya çekilmesini emretti. Aileler arabaları ve hayvanlarıyla hisarlarda toplanırken, Severinus'un keşişleri onun naaşını yolculuk için hazırlıyor.",
   OrganizeTheMarchToItalia: "Italia'ya yürüyüşü tertip et",
   HoldTheFortifiedTowns: "Tahkim edilmiş kasabaları muhafaza et",
   NegotiateTermsWithOdoacer: "Odoacer ile şartları müzakere et",
   ThreeRoadsToWar: "Harbe Giden Üç Yol",
   ThreeRoadsToWarDesc: "Celplerimiz toplanma meydanlarını dolduruyor ve gelirlerimiz bir imparatorluk seferini desteklemeye kafidir. Önümüzde üç yol açılıyor: batıda Alp geçitleri, güneyde Italia ve doğuda Tuna yolu. İmparatorluk sarayına arzuhal sunarken meclisimiz hangi seferi destekleyeceğine karar vermelidir.",
   PetitionForARaetianCampaign: "Bir Raetia seferi için arzuhal sun",
   PetitionForAnItalianCampaign: "Bir Italia seferi için arzuhal sun",
   PetitionForAPannonianCampaign: "Bir Pannonia seferi için arzuhal sun",
   TheSeawardGate: "Deniz Kapısı",
   TheSeawardGateDesc: "Dört sahil toprağı artık idaremize biat ediyor. Nehir yolları otoritemizi Adriyatik'e taşıyarak ticaret ve vergilendirme için yeni bir çıkış açtı. Sahilin evvela hazineyi mi, kasabaları mı yoksa eyalet makamlarını mı zenginleştireceğine karar vermeliyiz.",
   OpenTheCoastalMarkets: "Sahil pazarlarını aç",
   ExtendTheTaxOffices: "Vergi idarelerini teşmil et",
   TheAlpineBalance: "Alp Muvazenesi",
   TheAlpineBalanceDesc:
      "Bizim çekirdeğimiz katılaşırken Raetia'nın Alp hududundaki hakimiyeti zayıfladı. Diplomatları halen sulh arayışında, lakin geçitler ve hudut kasabaları menzilimiz dahilindedir. Kendi şartlarımızla himaye mi teklif edeceğimize, yoksa batı hududu üzerinde bir savaş için imparatorluk sarayına arzuhal mi sunacağımıza karar vermeliyiz.",
   OfferRaetiaOurProtection: "Raetia'ya himayemizi teklif et",
   PetitionForWarOverThePasses: "Geçitler üzerinden savaş için arzuhal sun",
   OurRealmOfManyPeoplesDesc: "Kanunlarımız artık Italia'dan Pannonia ve Raetia'ya uzanan yolları birbirine bağlıyor. Birçok kavim ve inanç, eski eyaletten çok daha büyük bir diyarı paylaşıyor. Meclisimiz bu yeni topluluğu bir arada tutacak olan prensibin ne olması gerektiğini soruyor.",
   PetitionForAMandateToRule: "Hükmetmek için bir emirname talep et",
   TolerateTheGatheredFaiths: "Bir araya gelen inançlara müsamaha göster",
   TolerateTheGatheredCultures: "Bir araya gelen kültürlere müsamaha göster",
   TheDalmatianFrontier: "Dalmatia Hududu",
   TheDalmatianFrontierDesc: "Sancaklarımız artık Dalmatia'da üç çekirdek toprağı elinde tutuyor; bu bize güneyde bir hudut ve Adriyatik boyunca yeni bir rota sunuyor. Hududu emniyete mi alacağımıza, zaferi mi kutlayacağımıza yoksa kuvvetlerimizi başka bir sefer için mi hazırlayacağımıza karar vermeliyiz.",
   SecureTheSouthernFrontier: "Güney hududunu emniyete al",
   CelebrateOurAdriaticVictory: "Adriyatik zaferimizi kutla",
   PrepareTheNextCampaign: "Bir sonraki seferi hazırla",
   BeyondTheDanube: "Tuna'nın Ötesi",
   BeyondTheDanubeDesc: "Üç Germania toprağı artık kanunlarımıza biat ediyor. Tuna artık bir hudut değil, nehirlerin, yolların ve yabancı kavimlerin diyarına giden bir yoldur. Otoritemizi daha ileriye hangi kudretin taşıyacağını seçmeliyiz: idare, diplomasi yahut silah.",
   BuildTheNewAdministration: "Yeni idareyi tesis et",
   SendEnvoysAcrossTheDanube: "Tuna'nın ötesine elçiler yolla",
   PutTheFrontierUnderArms: "Hududu silahlandır",
   $1IsNotOnTheMap: "<Province>$1</Province> haritada değil",
   AquincumBecomesAColonia: "Aquincum Colonia Oluyor",
   AquincumBecomesAColoniaDesc: "Aquincum, Septimius Severus idaresinde colonia mertebesine yükseltildi. Meclisi yeni imtiyazlar beklerken; gaziler, tacirler ve komşu cemiyetler şehrin bu yüksek statüsünden kimin istifade edeceğine karar vermemiz için bize baskı yapıyor.",
