   GreatWorkRoyalMausoleumOfMauretania: "Mauretania Kraliyet Mozolesi",
   $1AD: "MS $1",
   $1BC: "MÖ $1",
   $1IsCompletedIn$2ItsEffectAppliesAfterCompletion: "$1 <b>$2</b> içinde tamamlanır. Tesiri tamamlandıktan sonra tatbik edilir.",
   ClickToPanToTheGreatWorkTile: "Haritayı ulu eser toprağına kaydırmak için tıkla",
   ProvincialGreatWorks: "Eyalet Ulu Eserleri",
   GreatWorks: "Ulu Eserler",
   ShowAllGreatWorks: "Tüm Ulu Eserleri Göster",
   GreatWorkCompletedDesc$1$2: "Nihayet, $1 <Tile>$2</Tile> toprağında tamamlandı. Sayısız el cesur bir vizyonu taşa dönüştürdü ve henüz doğmamış nesiller bu zafere çağımızın ihtirasının ve dehasının bir abidesi olarak bakacaktır.",
   LetItsGloryEndureThroughTheAges: "Bırakın ihtişamı çağlar boyu sürsün",
   GreatWorkCompletedEffectsActive$1$2$3: "<i>$1</i> ($2), $3 içinde tamamlandı - tesirleri artık faaldir.",
   $1IsInRebellion: "<Tile>$1</Tile> isyan halinde!",
   EachCoreMadeAdds$1OfTheBaseCost$2CoresHaveBeenMade: "Çekirdek yapılan her bir toprak taban maliyete $1 ekler. $2 çekirdek yapıldı.",
   LegacyPointsForNextRun: "Sonraki Oyun İçin Miras Puanları",
   LegacyPointsFromPreviousRuns: "Önceki Oyunlardan Miras Puanları",
   EachAnnexedAndCoredTileGrants$1LegacyPoint: "İlhak edilip çekirdek yapılan her toprak $1 Miras Puanı bahşeder.",
   PersonalBestBonus: "Şahsi Rekor Bonusu",
   PersonalBestBonusDesc$1$2: "Önceki rekorumuzun ötesinde ilhak edilip çekirdek yapılan her toprak fazladan $1 Miras Puanı bahşeder. Önceki rekor: $2 toprak.",
   CannotLookForSpouseWhileFamilyHasChildren: "Ailede çocuk varken eş aranamaz; aksi halde çocuklar haneden çıkarılırdı.",
   WelcomeTheChildIntoOurFamily: "Çocuğu hanemize buyur et",
   AChildIsBorn: "Bir Çocuk Dünyaya Geldi",
   AChildIsBornDesc$1$2$3$4$5: "A child is born into the ruling house: $1 ($2 Administrative, $3 Diplomatic, $4 Military, $5). The family welcomes its newest member, and the province looks to the future with hope.",
   AQuestionOfLegitimacyDesc$1$2$3$4$5:
      "Word has reached us that a young child named $1 ($2 Administrative, $3 Diplomatic, $4 Military, $5) has appeared at court. The child is said to be of our governor's blood, and although the circumstances of the birth are shrouded in secrecy and scandal, no one can deny the resemblance.",
   ANewGovernorDesc$1$2$3$4$5$6: "İhtiyar vali bu dünyadan göçtü, lakin hazırlıksız değil. Varisi $1 ($2 İdari, $3 Diplomatik, $4 Askeri, $5 yaşında, $6 evlat), idarenin yükünü omuzlamak üzere öne çıkıyor. Devlet çarkları dönmeye devam ediyor—eskiye nazaran biraz daha yavaş olsa da.",
   TheGovernorDiesWithoutAnHeirAndForAMomentNoOneRulesDesc$1$2$3$4$5$6:
      "Vali varis bırakmadan vefat etti ve bir anlığına kimse hükmedemedi. Senato, halef olarak $1'i tayin etti ($2 İdari, $3 Diplomatik, $4 Askeri, $5 yaşında, $6 evlat), lakin uzaktan dayatılan otorite tam oturmuyor. Nizam sürüyor, lakin itimat sarsıldı.",
   $1$2JoinsTheGovernorsFamily: "$1 ($2) joins the governor's family.",
   $1$2DoesNotJoinTheGovernorsFamily: "$1 ($2) does not join the governor's family.",
   ResearchedProvinceDiscount$1$2: "Bu teknolojiyi araştıran her eyalet, maliyeti taban maliyetin $1'i kadar düşürür. Bu teknolojiyi $2 eyalet araştırdı",
