   ConscriptionReductionWarning$1$2$2: "Lowering Target Conscription from $1 to $2 will <i>immediately</i> reduce Actual Conscription to $2, shrinking your standing army. Rebuilding your standing army takes time.",
   ArmyMaintenanceReductionWarning$1$2$2: "Lowering Army Maintenance from $1 to $2 will <i>immediately</i> reduce Current Morale to $2. Morale takes time to recover, even after Army Maintenance is raised again.",
   SkipConfirmationWhenLoweringConscription: "Skip confirmation when lowering conscription",
   SkipConfirmationWhenLoweringArmyMaintenance: "Skip confirmation when lowering army maintenance",
   Effectiveness: "Effectiveness",
   $1Units$2Power: "$1 units × $2 power",
   Vs$1: "vs. $1",
   CombinedPower: "Combined Power",
   GeneralSkillBasePowerDesc$1: "Each general skill level adds $1 of the corresponding unit's base power.",
   InfantryCountersCavalryAndIsCounteredByRangedUnits: "Infantry counters <i>cavalry</i> and is countered by <i>ranged units</i>.",
   InfantryEffectivenessIncreaseDesc$1$2: "Each $1 of the enemy's war power contributed by cavalry <i>increases</i> our infantry's effectiveness by $2.",
   InfantryEffectivenessDecreaseDesc$1$2: "Each $1 of the enemy's war power contributed by ranged units <i>decreases</i> our infantry's effectiveness by $2.",
   RangedUnitsCounterInfantryAndAreCounteredByCavalry: "Ranged units counter <i>infantry</i> and are countered by <i>cavalry</i>.",
   RangedEffectivenessIncreaseDesc$1$2: "Each $1 of the enemy's war power contributed by infantry <i>increases</i> our ranged units' effectiveness by $2.",
   RangedEffectivenessDecreaseDesc$1$2: "Each $1 of the enemy's war power contributed by cavalry <i>decreases</i> our ranged units' effectiveness by $2.",
   CavalryCountersRangedUnitsAndIsCounteredByInfantry: "Cavalry counters <i>ranged units</i> and is countered by <i>infantry</i>.",
   CavalryEffectivenessIncreaseDesc$1$2: "Each $1 of the enemy's war power contributed by ranged units <i>increases</i> our cavalry's effectiveness by $2.",
   CavalryEffectivenessDecreaseDesc$1$2: "Each $1 of the enemy's war power contributed by infantry <i>decreases</i> our cavalry's effectiveness by $2.",
   CavalryPredominanceDesc$1$2$3: "$1 War Power for each $2 Cavalry Unit composition (up to $3)",
   RangedPredominanceDesc$1$2$3: "$1 War Power for each $2 Ranged Unit composition (up to $3)",
   ExecuteABattlePlan: "Execute a Battle Plan",
   TimedActionExecuteBattlePlanDesc$1: "Spend $1 general skill point to gain war score equal to the sum of our general's infantry, ranged, and cavalry skill levels.",
   MakeWarSpeechDesc$1$2: "Making a war speech grants us $1 of the required war score (rounded down, minimum $2) and can only be done within the first year of the war.",
   DecimateOurArmyDesc$1$2$3: "Decimating our army reduces our standing army by $1 and grants us $2 of the required war score (rounded down, minimum $3).",
   NoTruceBetween$1And$2: "No truce between $1 and $2",
